from abc import ABC, abstractmethod
class Extension(ABC):
    @abstractmethod
    def evaluate(self): pass
class Registry:
    def register(self, cls: type[Extension]) -> None:
        if not isinstance(cls, type) or not issubclass(cls, Extension):
            raise TypeError('not a valid extension')
        self._plugins.append(cls)

